"use client";
import {useState,type FormEvent} from "react";
import Link from "next/link";
import {useRouter} from "next/navigation";
import {memberRequest,useMember} from "./member-provider";
export function AccountForm(){const {user,loading,setUser}=useMember();const router=useRouter();const [busy,setBusy]=useState(false);const [message,setMessage]=useState("");const [error,setError]=useState("");
 async function submit(e:FormEvent<HTMLFormElement>,action:"profile"|"delete"){e.preventDefault();const form=e.currentTarget;const data=Object.fromEntries(new FormData(form));if(action==="profile"&&data.newPassword!==data.confirmPassword){setError("새 비밀번호 확인이 일치하지 않습니다.");return}if(!data.newPassword)delete data.newPassword;setBusy(true);setMessage("");setError("");try{const result=await memberRequest(action,data);if(action==="delete"){setUser(null);router.replace("/login")}else{setUser(result.user);form.reset();setMessage("회원정보를 저장했습니다. 다른 기기의 로그인은 해제되었습니다.")}}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 if(loading)return <p>회원정보를 불러오는 중입니다.</p>;
 if(!user)return <section className="member-card"><h1>로그인이 필요합니다</h1><Link href="/login">로그인하기 →</Link></section>;
 return <><p className="member-eyebrow">MY ACCOUNT</p><h1>회원정보 관리</h1><div className="member-account-grid"><section className="member-card"><h2>기본 정보와 비밀번호</h2><form key={`${user.id}-${user.loginId}-${user.email}-${user.name}`} onSubmit={e=>submit(e,"profile")}><fieldset disabled={busy}><label>아이디<input name="loginId" defaultValue={user.loginId} required pattern="[A-Za-z0-9_]{4,30}" autoComplete="username"/></label><label>이름<input name="name" defaultValue={user.name} required maxLength={50} autoComplete="name"/></label><label>이메일<input name="email" defaultValue={user.email} required type="email" autoComplete="email"/></label><label>현재 비밀번호<input name="currentPassword" type="password" required autoComplete="current-password"/></label><label>새 비밀번호 (변경할 때만)<input name="newPassword" type="password" minLength={12} maxLength={72} autoComplete="new-password"/></label><label>새 비밀번호 확인<input name="confirmPassword" type="password" autoComplete="new-password"/></label><button className="member-primary">정보 저장</button></fieldset></form></section><section className="member-card member-withdraw"><h2>회원탈퇴</h2><p>계정과 개인정보, 저장한 장바구니가 삭제되며 모든 기기에서 로그아웃됩니다. 되돌릴 수 없습니다. 기존 주문 내역은 계정 연결을 해제한 상태로 남습니다.</p><form onSubmit={e=>submit(e,"delete")}><fieldset disabled={busy}><label>현재 비밀번호<input name="currentPassword" type="password" required autoComplete="current-password"/></label><label>확인을 위해 ‘회원탈퇴’를 입력하세요<input name="confirmation" required pattern="회원탈퇴" autoComplete="off"/></label><button className="member-danger">회원탈퇴</button></fieldset></form></section></div>{error&&<p role="alert" className="member-error">{error}</p>}{message&&<p role="status" className="member-success">{message}</p>}</>;
}
